230		private void onOptionsButtonClick(final View view, YouTubeVideo youTubeVideo) {
231			final PopupMenu popupMenu = createPopup(R.menu.video_options_menu, view);
232			final Menu menu = popupMenu.getMenu();
233			compositeDisposable.add(DatabaseTasks.isVideoBookmarked(youTubeVideo.getId(), menu));
234	
235			// If playback history is not disabled, see if this video has been watched. Otherwise, hide the "mark watched" & "mark unwatched" options from the menu.
236			if (SkyTubeApp.getSettings().isPlaybackStatusEnabled()) {
237				compositeDisposable.add(DatabaseTasks.isVideoWatched(youTubeVideo.getId(), menu));
238			} else {
239				menu.findItem(R.id.mark_watched).setVisible(false);
240				menu.findItem(R.id.mark_unwatched).setVisible(false);
241			}
242	
243			boolean online = SkyTubeApp.isConnected(view.getContext());
244	
245			menu.findItem(R.id.download_video).setVisible(false);
246			menu.findItem(R.id.delete_download).setVisible(false);
247	
248			compositeDisposable.add(DownloadedVideosDb.getVideoDownloadsDb().isVideoDownloaded(youTubeVideo).subscribe(isDownloaded -> {
249				if(isDownloaded) {
250					menu.findItem(R.id.delete_download).setVisible(true);
251				} else {
252					menu.findItem(R.id.download_video).setVisible(online);
253				}
254			}));
255	
256			actionHandler.updateBlockingMenuItem(menu);
257			actionHandler.updateSubscribeMenuItem(youTubeVideo.getChannelId(), menu);
258	
259			popupMenu.setOnMenuItemClickListener(item -> {
260				if (actionHandler.handleChannelActions(context, youTubeVideo.getChannel(), item.getItemId())) {
261					return true;
262				}
263				switch(item.getItemId()) {
264					case R.id.menu_open_video_with:
265						compositeDisposable.add(youTubeVideo.playVideoExternally(context).subscribe());
266						return true;
267					case R.id.share:
268						youTubeVideo.shareVideo(view.getContext());
269						return true;
270					case R.id.copyurl:
271						youTubeVideo.copyUrl(context);
272						return true;
273					case R.id.mark_watched:
274						compositeDisposable.add(
275								PlaybackStatusDb.getPlaybackStatusDb().setVideoWatchedStatusInBackground(youTubeVideo, true)
276										.subscribe((success) -> updateViewsData()));
277						return true;
278					case R.id.mark_unwatched:
279						compositeDisposable.add(
280								PlaybackStatusDb.getPlaybackStatusDb().setVideoWatchedStatusInBackground(youTubeVideo, false)
281										.subscribe((success) -> updateViewsData()));
282						return true;
283					case R.id.bookmark_video:
284						compositeDisposable.add(youTubeVideo.bookmarkVideo(context, menu).subscribe());
285						return true;
286					case R.id.unbookmark_video:
287						compositeDisposable.add(youTubeVideo.unbookmarkVideo(context, menu).subscribe());
288						return true;
289					case R.id.view_thumbnail:
290						Intent i = new Intent(context, ThumbnailViewerActivity.class);
291						i.putExtra(ThumbnailViewerActivity.YOUTUBE_VIDEO, youTubeVideo);
292						context.startActivity(i);
293						return true;
294					case R.id.delete_download:
295						compositeDisposable.add(
296								DownloadedVideosDb.getVideoDownloadsDb().removeDownload(context, youTubeVideo.getVideoId()).subscribe());
297						return true;
298					case R.id.download_video:
299						final Policy decision = new MobileNetworkWarningDialog(view.getContext())
300								.showDownloadWarning(youTubeVideo);
301	
302						if (decision == Policy.ALLOW) {
303							youTubeVideo.downloadVideo(context).subscribe();
304						}
305						return true;
306				}
307				return false;
308			});
309			popupMenu.show();
310		}
