500		 * Downloads this video.
501		 *
502		 * @return The download task.
503		 * @param context Context
504		 */
505		public Completable downloadVideo(final Context context) {
506			return DownloadedVideosDb.getVideoDownloadsDb().isVideoDownloaded(YouTubeVideo.this.getVideoId())
507					.flatMapCompletable((downloadedVideo) -> {
508				if (downloadedVideo) {
509					return Completable.complete();
510				} else {
511					return YouTubeTasks.getDesiredStream(this, new GetDesiredStreamListener() {
512						@Override
513						public void onGetDesiredStream(StreamInfo streamInfo, YouTubeVideo video) {
514	
515							final Settings settings = SkyTubeApp.getSettings();
516							StreamSelectionPolicy selectionPolicy = settings.getDesiredVideoResolution(true);
517							StreamSelectionPolicy.StreamSelection streamSelection = selectionPolicy.select(streamInfo);
518							if (streamSelection != null) {
519								VideoStream videoStream = streamSelection.getVideoStream();
520								// download the video
521								downloadTheVideo(videoStream, settings);
522							} else {
523								Toast.makeText(context, selectionPolicy.getErrorMessage(context), Toast.LENGTH_LONG).show();
524							}
525						}
526	
527						private void downloadTheVideo(Stream stream, Settings settings) {
528							new VideoDownloader()
529									.setRemoteFileUrl(stream.getUrl())
530									.setDirType(Environment.DIRECTORY_MOVIES)
531									.setTitle(getTitle())
532									.setDescription(getStr(R.string.video) + " ― " + getChannelName())
533									.setOutputFileName(getId() + " - " + getTitle())
534									.setOutputDirectoryName(getChannelName())
535									.setParentDirectory(settings.getDownloadParentFolder())
536									.setOutputFileExtension(stream.getFormat().suffix)
537									.setAllowedOverRoaming(false)
538									.setAllowedNetworkTypesFlags(DownloadManager.Request.NETWORK_WIFI | DownloadManager.Request.NETWORK_MOBILE)
539									.displayPermissionsActivity(context);
540						}
541	
542						@Override
543						public void onGetDesiredStreamError(Throwable throwable) {
544							Logger.e(YouTubeVideo.this, "Stream error: " + throwable.getMessage(), throwable);
545							Context context = getContext();
546							Toast.makeText(context,
547									String.format(context.getString(R.string.video_download_stream_error), getTitle()),
548									Toast.LENGTH_LONG).show();
549						}
550					});
551				}
552			});
553		}
