558		public Single<DownloadedVideosDb.Status> playVideoExternally(Context context) {
559			return DownloadedVideosDb.getVideoDownloadsDb().getDownloadedFileStatus(context, getVideoId()).map(fileStatus -> {
560				if (fileStatus.getLocalVideoFile() != null) {
561					Uri uri;
562					File file = fileStatus.getLocalVideoFile();
563					try {
564						uri = FileProvider.getUriForFile(context, BuildConfig.APPLICATION_ID + ".provider", file);
565					} catch (Exception e) {
566						Logger.e(YouTubeVideo.this, "Error accessing path: " + file + ", message:" + e.getMessage(), e);
567						uri = fileStatus.getUri();
568					}
569					Intent intent = new Intent(Intent.ACTION_VIEW, uri);
570					intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
571					context.startActivity(intent);
572				} else {
573					Intent browserIntent = new Intent(Intent.ACTION_VIEW, Uri.parse(getVideoUrl()));
574					context.startActivity(browserIntent);
575				}
576				return fileStatus;
577			});
578		}
