44	/**
45	 * A {@link android.widget.TextView} which is able to handle clicks on links within the set text.
46	 * YouTube related links are handled by the app itself, while other links are handled by third-
47	 * party Android apps.
48	 */
49	public class Linker {
50	
51		private final static String TAG = Linker.class.getSimpleName();
52	
53		public interface CurrentActivity {
54	
55			boolean canNavigateTo(ContentId contentId);
56		}
57	
58		public static void configure(TextView textView, CurrentActivity currentActivity) {
59			textView.setAutoLinkMask(0);
60			textView.setMovementMethod(new TouchableMovementMethod(new LinkListener(textView.getContext(), currentActivity)));
61		}
62	
63		/**
64		 * Sets the text to be displayed and ensure that any links (in the text) are clickable.
65		 *
66		 * @param text
67		 */
68		public static void setTextAndLinkify(TextView textView, String text) {
69			final Spanned spans = span(text);
70			textView.setText(spans);
71		}
72	
73		private static Spanned span(String text) {
74			if (isText(text)) {
75				return spanText(text);
76			} else {
77				return HtmlCompat.fromHtml(text, HtmlCompat.FROM_HTML_MODE_LEGACY);
78			}
79		}
80	
81		private static boolean isText(String text) {
82			String lower = text.toLowerCase();
83			return (!lower.contains("<a ") && !lower.contains("<br"));
84		}
85	
86		private static Spanned spanText(String text) {
87			SpannableStringBuilder spanner = new SpannableStringBuilder(text.replaceAll("&nbsp;", " "));
88			LinkifyCompat.addLinks(spanner, Linkify.WEB_URLS);
89			return spanner;
90		}
91	
92		/**
93		 * Certain kinds of URLs are to be opened from within
94		 * the app itself (i.e. YouTube video urls, playlist urls, etc); all other URLs are to be opened
95		 * by using third party Android apps.
96		 *
97		 * Furthermore, all long clicks are captured to show a menu to open, copy, or share the url.
98		 */
99		static class LinkListener implements TouchableMovementMethod.URLSpanClickListener {
100			private final Context ctx;
101			private final CurrentActivity currentActivity;
102			LinkListener(Context ctx, CurrentActivity currentActivity) {
103				this.ctx = ctx;
104				this.currentActivity = currentActivity;
105			}
106	
107			@Override
108			public void onClick(URLSpan span, boolean longClick) {
109				String clickedText = span.getURL();
110				ContentId content = SkyTubeApp.parseUrl(ctx, clickedText, false);
111				if (longClick) {
112					longClick(clickedText, content);
113				} else {
114					if (currentActivity != null && content != null && currentActivity.canNavigateTo(content)) {
115						return;
116					} else {
117						SkyTubeApp.openUrl(ctx, clickedText, true);
118					}
119				}
120			}
121	
122			private void longClick(String clickedText, ContentId content) {
123				List<String> items = new ArrayList<>(Arrays.asList(ctx.getString(R.string.open_in_browser), ctx.getString(R.string.copy_url), ctx.getString(R.string.share_via)));
124				final boolean isBookmarked;
125				if(content != null && content.getType() == StreamingService.LinkType.STREAM) {
126					isBookmarked = BookmarksDb.getBookmarksDb().isBookmarked(content.getId());
127					if(isBookmarked) {
128						items.add(ctx.getString(R.string.unbookmark));
129					} else {
130						items.add(ctx.getString(R.string.bookmark));
131					}
132				} else {
133					isBookmarked = false;
134				}
135				new AlertDialog.Builder(ctx)
136						.setTitle(clickedText)
137						.setItems(items.toArray(new CharSequence[0]),
138								(dialog, which) -> {
139									switch (which) {
140										case 0:
141											SkyTubeApp.viewInBrowser(clickedText, ctx);
142											break;
143										case 1:
144											SkyTubeApp.copyUrl(ctx, "URL", clickedText);
145											break;
146										case 2:
147											Intent intent = new Intent(Intent.ACTION_SEND);
148											intent.setType("text/plain");
149											intent.putExtra(Intent.EXTRA_TEXT, clickedText);
150											ctx.startActivity(Intent.createChooser(intent, ctx.getString(R.string.share_via)));
151											break;
152										case 3:
153											YouTubeTasks.getVideoDetails(ctx, content)
154													.flatMapSingle(video -> {
155														if(!isBookmarked) {
156															return video.bookmarkVideo(ctx);
157														} else {
158															return video.unbookmarkVideo(ctx, null);
159														}
160													}).subscribe();
161											break;
162									}
163								})
164						.show();
165			}
